def find_path(graph, start, goal):
    # Initialize data structures
    visited = set()  # Nodes already visited
    path = {start: [start]}  # Stores path from start to each node

    # Depth-First Search (DFS)
    def dfs(node, goal):
        if node in visited:
            return None
        visited.add(node)
        if node == goal:
            return [node]
        for neighbor in graph.get(node, []):
            path_for_neighbor = dfs(neighbor, goal)
            if path_for_neighbor is not None:
                path_for_neighbor.insert(0, node)
                return path_for_neighbor
        return None

    # Perform DFS
    return dfs(start, goal)
