    stack = [(start, [start])]  # Stack to hold tuples of (node, path)

    while stack:
        (current_node, path) = stack.pop()
        if current_node in visited:
            continue
        visited.add(current_node)

        if current_node == goal:
            return path

        # Explore neighboring nodes
