def find_path(graph, start, goal):
    # Initialize the path and visited set
    path = []
    visited = set()

    # Helper function to check if a node is in the visited set
    def is_visited(node):
        return node in visited

    # Function to do a depth-first search
    def dfs(node, path):
        if node == goal:
            return True
        elif is_visited(node):
            return False
        visited.add(node)
        path.append(node)
        for neighbour in graph.get(node, []):
            if dfs(neighbour, path):
                return True
        path.pop()
        visited.remove(node)
        return False

    if start == goal:
        return [start]

    dfs(start, path)

    # If the goal is not in the visited set, it's unreachable
    if goal not in visited:
        return None
    else:
        return path
